import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry matching atlas region aspect ratio (512x320 = 1.6:1)
  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Prepare material with texture node
  const material = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    toneMapped: false,
  });

  // Load the ceramic grain texture and apply with UV mapping for atlas region
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  let textureNode = uniform(null);

  texturePromise.then((texture) => {
    texture.flipY = false;
    // Atlas region: 0,0,512,320 in 512x320 sheet = full texture
    // Standard UV mapping covers the region
    material.colorNode = textureNode.assign(texture);
    material.needsUpdate = true;
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.scale.set(1, 1, 1);

  // Build the returned object
  const group = new THREE.Group();
  group.add(mesh);

  // Cleanup handler
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
